// ---- rpc ----

// Hello: Server identity and the negotiated protocol.
type Hello struct {
	// Protocol major version the server speaks.
	Protocol int64 `json:"protocol"`
	// Server name and version, for logs.
	Server string `json:"server"`
}

// RPCHelloParams holds the params of rpc.hello.
type RPCHelloParams struct {
	// Protocol major version the client speaks.
	Protocol int64 `json:"protocol"`
	// Client name and version, for logs.
	Client string `json:"client"`
}

// RPCService: Connection setup. A client calls rpc.hello first on every
// connection; the server answers any other method with notReady until hello
// succeeds.
type RPCService interface {
	// Hello implements rpc.hello. Negotiate the protocol major version. Changes
	// within a major version are additive only.
	Hello(ctx context.Context, p *RPCHelloParams) (*Hello, error)
}

func registerRPC(r *Router, s RPCService) {
	callers := []Caller{CallerLocal, CallerSession, CallerDevice}
	r.handle("rpc.hello", callers, func(ctx context.Context, raw jsontext.Value) (any, error) {
		var p RPCHelloParams
		if err := decodeParams(raw, &p, []string{"protocol", "client"}); err != nil {
			return nil, err
		}
		return s.Hello(ctx, &p)
	})
}

// RPCClient calls the rpc methods; it implements RPCService.
type RPCClient struct{ c *Client }

// RPC returns the rpc methods.
func (c *Client) RPC() RPCClient { return RPCClient{c} }

var _ RPCService = RPCClient{}

// Hello calls rpc.hello.
func (x RPCClient) Hello(ctx context.Context, p *RPCHelloParams) (*Hello, error) {
	var r Hello
	err := x.c.Call(ctx, "rpc.hello", p, &r)
	if err != nil {
		return nil, err
	}
	return &r, nil
}

// ---- vault ----

// ScanState: What a vault's scanner is doing.
type ScanState string

const (
	// No scan is running; the index holds what the last scan and the watcher
	// found.
	ScanStateIdle ScanState = "idle"
	// A scan is running.
	ScanStateScanning ScanState = "scanning"
	// The last scan failed and error says why; the index keeps what it held.
	ScanStateFailed ScanState = "failed"
)

// Valid reports whether v is one of the declared values.
func (v ScanState) Valid() bool {
	switch v {
	case ScanStateIdle, ScanStateScanning, ScanStateFailed:
		return true
	}
	return false
}

// ScanStatus: The state of a vault's index and its scans.
type ScanStatus struct {
	VaultID int64     `json:"vaultId"`
	State   ScanState `json:"state"`
	// Files the running scan has compared with the index; 0 when none runs.
	Done int64 `json:"done"`
	// Files the running scan found; 0 when none runs.
	Total int64 `json:"total"`
	// Notes in the index.
	Notes int64 `json:"notes"`
	// Attachments in the index.
	Attachments int64 `json:"attachments"`
	// When the last scan finished; absent until one has since notesd started.
	ScannedAt *time.Time `json:"scannedAt,omitzero"`
	// The vault is on a network file system, so notesd rescans it every 10
	// seconds instead of every 5 minutes.
	Network bool `json:"network"`
	// Why the last scan failed.
	Error *string `json:"error,omitzero"`
}

// Vault: A registered vault.
type Vault struct {
	// Stable local identifier.
	ID int64 `json:"id"`
	// Display name; the directory's base name unless one was given.
	Name string `json:"name"`
	// Absolute, cleaned path of the vault directory.
	Path      string    `json:"path"`
	CreatedAt time.Time `json:"createdAt"`
}

// VaultListParams holds the params of vault.list.
type VaultListParams struct{}

// VaultAddParams holds the params of vault.add.
type VaultAddParams struct {
	// Absolute path of the vault directory.
	Path string `json:"path"`
	// Display name; defaults to the directory's base name.
	Name *string `json:"name,omitzero"`
}

// VaultRemoveParams holds the params of vault.remove.
type VaultRemoveParams struct {
	ID int64 `json:"id"`
}

// VaultStatusParams holds the params of vault.status.
type VaultStatusParams struct {
	ID int64 `json:"id"`
}

// VaultReindexParams holds the params of vault.reindex.
type VaultReindexParams struct {
	ID int64 `json:"id"`
}

// VaultService: The vaults this notesd owns: directories of markdown notes
// (ADR-0003). Registering a vault never writes to it.
type VaultService interface {
	// List implements vault.list. Every registered vault, by name.
	List(ctx context.Context, p *VaultListParams) ([]Vault, error)
	// Add implements vault.add. Register a directory as a vault. The path must be
	// absolute and name an existing directory, and no registered vault may
	// contain it or lie inside it.
	Add(ctx context.Context, p *VaultAddParams) (*Vault, error)
	// Remove implements vault.remove. Forget a vault. Its directory and files are
	// untouched.
	Remove(ctx context.Context, p *VaultRemoveParams) error
	// Status implements vault.status. The state of a vault's index and its scans.
	Status(ctx context.Context, p *VaultStatusParams) (*ScanStatus, error)
	// Reindex implements vault.reindex. Read every file of a vault again and
	// rebuild its index, as if none matched it. File IDs and versions are kept,
	// so nothing is lost. The scan runs in the background; vault.scan events
	// report its progress.
	Reindex(ctx context.Context, p *VaultReindexParams) (*ScanStatus, error)
}

func registerVault(r *Router, s VaultService) {
	callers := []Caller{CallerLocal}
	r.handle("vault.list", callers, func(ctx context.Context, raw jsontext.Value) (any, error) {
		var p VaultListParams
		if err := decodeParams(raw, &p, nil); err != nil {
			return nil, err
		}
		return s.List(ctx, &p)
	})
	r.handle("vault.add", callers, func(ctx context.Context, raw jsontext.Value) (any, error) {
		var p VaultAddParams
		if err := decodeParams(raw, &p, []string{"path"}); err != nil {
			return nil, err
		}
		return s.Add(ctx, &p)
	})
	r.handle("vault.remove", callers, func(ctx context.Context, raw jsontext.Value) (any, error) {
		var p VaultRemoveParams
		if err := decodeParams(raw, &p, []string{"id"}); err != nil {
			return nil, err
		}
		return nil, s.Remove(ctx, &p)
	})
	r.handle("vault.status", callers, func(ctx context.Context, raw jsontext.Value) (any, error) {
		var p VaultStatusParams
		if err := decodeParams(raw, &p, []string{"id"}); err != nil {
			return nil, err
		}
		return s.Status(ctx, &p)
	})
	r.handle("vault.reindex", callers, func(ctx context.Context, raw jsontext.Value) (any, error) {
		var p VaultReindexParams
		if err := decodeParams(raw, &p, []string{"id"}); err != nil {
			return nil, err
		}
		return s.Reindex(ctx, &p)
	})
}

