// Services is one implementation per domain, for NewRouter.
type Services struct {
	Events EventsService
	Note   NoteService
	RPC    RPCService
	Vault  VaultService
}

func (s Services) register(r *Router) error {
	if s.Events == nil {
		return errors.New("api: Services.Events is nil")
	}
	registerEvents(r, s.Events)
	if s.Note == nil {
		return errors.New("api: Services.Note is nil")
	}
	registerNote(r, s.Note)
	if s.RPC == nil {
		return errors.New("api: Services.RPC is nil")
	}
	registerRPC(r, s.RPC)
	if s.Vault == nil {
		return errors.New("api: Services.Vault is nil")
	}
	registerVault(r, s.Vault)
	return nil
}

// Methods is every method's wire name, in schema order.
var Methods = []string{
	"events.subscribe",
	"note.list",
	"note.read",
	"note.search",
	"note.backlinks",
	"note.links",
	"note.create",
	"note.write",
	"note.move",
	"note.delete",
	"note.versions",
	"note.revert",
	"note.daily",
	"rpc.hello",
	"vault.list",
	"vault.add",
	"vault.remove",
	"vault.status",
	"vault.reindex",
}

// DecodeEvent decodes the data of the named event.
func DecodeEvent(name string, data jsontext.Value) (Event, error) {
	switch name {
	case "note.changed":
		var e NoteChanged
		if err := json.Unmarshal(data, &e); err != nil {
			return nil, fmt.Errorf("decode event %s: %w", name, err)
		}
		return e, nil
	case "note.moved":
		var e NoteMoved
		if err := json.Unmarshal(data, &e); err != nil {
			return nil, fmt.Errorf("decode event %s: %w", name, err)
		}
		return e, nil
	case "note.removed":
		var e NoteRemoved
		if err := json.Unmarshal(data, &e); err != nil {
			return nil, fmt.Errorf("decode event %s: %w", name, err)
		}
		return e, nil
	case "vault.scan":
		var e VaultScan
		if err := json.Unmarshal(data, &e); err != nil {
			return nil, fmt.Errorf("decode event %s: %w", name, err)
		}
		return e, nil
	case "vault.added":
		var e VaultAdded
		if err := json.Unmarshal(data, &e); err != nil {
			return nil, fmt.Errorf("decode event %s: %w", name, err)
		}
		return e, nil
	case "vault.removed":
		var e VaultRemoved
		if err := json.Unmarshal(data, &e); err != nil {
			return nil, fmt.Errorf("decode event %s: %w", name, err)
		}
		return e, nil
	}
	return nil, fmt.Errorf("unknown event %q", name)
}
